@IsTest
private class CheckboxReadObservation {
    private static void emit(String cell, Map<String,Object> row) {
        row.put('cell', cell);
        row.put('sourceApi', '62.0');
        row.put('callerApi', '62.0');
        System.assertEquals('capture', 'CHECKBOX_READ_OBSERVATION ' + JSON.serialize(row));
    }
    @IsTest static void absent() { emit('absent', OwnedCheckboxRead.describe(new Contact())); }
    @IsTest static void absentWithId() { emit('absentWithId', OwnedCheckboxRead.describe(new Contact(Id='003000000000072', LastName='Owned'))); }
    @IsTest static void absentWithParent() { emit('absentWithParent', OwnedCheckboxRead.describe(OwnedCheckboxRead.related())); }
    @IsTest static void explicitNullConstructor() { emit('explicitNullConstructor', OwnedCheckboxRead.describe(new Contact(DoNotCall=null))); }
    @IsTest static void explicitNullPut() {
        Contact row = new Contact();
        row.put('DoNotCall', null);
        emit('explicitNullPut', OwnedCheckboxRead.describe(row));
    }
    @IsTest static void explicitFalse() { emit('explicitFalse', OwnedCheckboxRead.describe(new Contact(DoNotCall=false))); }
    @IsTest static void explicitTrue() { emit('explicitTrue', OwnedCheckboxRead.describe(new Contact(DoNotCall=true))); }
    @IsTest static void userPropertyNull() {
        OwnedCheckboxRead.ValueHolder holder = new OwnedCheckboxRead.ValueHolder();
        Object value = holder.value;
        emit('userPropertyNull', new Map<String,Object>{'dot'=>holder.value, 'cast'=>OwnedCheckboxRead.castValue(value)});
    }
    @IsTest static void keyCollections() { emit('keyCollections', OwnedCheckboxRead.keys()); }
}

