public class OwnedCheckboxRead {
    public class ValueHolder { public Boolean value { get; set; } }

    public static Map<String,Object> describe(Contact row) {
        Map<String,Object> answer = new Map<String,Object>();
        try { answer.put('stringGet', row.get('DoNotCall')); }
        catch (Exception ex) { answer.put('stringError', ex.getTypeName() + ': ' + ex.getMessage()); }
        try { answer.put('tokenGet', row.get(Contact.DoNotCall)); }
        catch (Exception ex) { answer.put('tokenError', ex.getTypeName() + ': ' + ex.getMessage()); }
        try { answer.put('dot', row.DoNotCall); }
        catch (Exception ex) { answer.put('dotError', ex.getTypeName() + ': ' + ex.getMessage()); }
        try { answer.put('cast', castValue(row.get('DoNotCall'))); }
        catch (Exception ex) { answer.put('castError', ex.getTypeName() + ': ' + ex.getMessage()); }
        return answer;
    }

    public static Boolean castValue(Object value) { return (Boolean)value; }

    public static Contact related() {
        Account parent = new Account(Id='001000000000071', Name='Owned');
        Contact row = new Contact(Id='003000000000071', AccountId=parent.Id, LastName='Owned');
        row.putSObject('Account', parent);
        return row;
    }

    public static Map<String,Object> keys() {
        Map<Boolean,Integer> counts = new Map<Boolean,Integer>();
        Set<Boolean> keys = new Set<Boolean>();
        for (Contact row : new List<Contact>{new Contact(DoNotCall=true), new Contact(DoNotCall=false), new Contact()}) {
            Boolean key = castValue(row.get('DoNotCall'));
            keys.add(key);
            counts.put(key, counts.containsKey(key) ? counts.get(key) + 1 : 1);
        }
        return new Map<String,Object>{'mapSize'=>counts.size(), 'setSize'=>keys.size(),
            'nullCount'=>counts.get(null), 'falseCount'=>counts.get(false), 'trueCount'=>counts.get(true),
            'setNull'=>keys.contains(null), 'setFalse'=>keys.contains(false), 'setTrue'=>keys.contains(true)};
    }
}

